#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

#define AES_BLOCK_SIZE 16
#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 60
#define MAX_REQUESTS_PER_WINDOW 100

typedef struct {
    uint8_t key[32];
    uint8_t iv_base[AES_BLOCK_SIZE];
    uint32_t generation_counter;
    pthread_mutex_t lock;
} pdf_crypto_ctx_t;

typedef struct {
    time_t window_start;
    int request_count;
    pthread_mutex_t rate_lock;
} rate_limiter_t;

typedef struct {
    uint8_t iv[AES_BLOCK_SIZE];
    uint8_t *ciphertext;
    size_t ct_len;
    uint32_t sequence_id;
} encrypted_stream_t;

static rate_limiter_t g_limiter = { .window_start = 0, .request_count = 0 };

static void derive_iv(pdf_crypto_ctx_t *ctx, uint8_t *out_iv, uint32_t seq) {
    memcpy(out_iv, ctx->iv_base, AES_BLOCK_SIZE);
    /* XOR the sequence number into bytes 12-15 of the IV */
    out_iv[12] ^= (seq >> 24) & 0xFF;
    out_iv[13] ^= (seq >> 16) & 0xFF;
    out_iv[14] ^= (seq >> 8) & 0xFF;
    out_iv[15] ^= seq & 0xFF;
}

static int check_rate_limit(rate_limiter_t *limiter) {
    time_t now = time(NULL);
    pthread_mutex_lock(&limiter->rate_lock);
    if (now - limiter->window_start >= RATE_LIMIT_WINDOW) {
        limiter->window_start = now;
        limiter->request_count = 0;
    }
    if (limiter->request_count >= MAX_REQUESTS_PER_WINDOW) {
        pthread_mutex_unlock(&limiter->rate_lock);
        return -1;
    }
    limiter->request_count++;
    pthread_mutex_unlock(&limiter->rate_lock);
    return 0;
}

static int aes_cbc_encrypt(const uint8_t *key, const uint8_t *iv,
                           const uint8_t *plaintext, size_t pt_len,
                           uint8_t **ciphertext, size_t *ct_len) {
    /* Simulated AES-CBC encryption */
    *ct_len = ((pt_len / AES_BLOCK_SIZE) + 1) * AES_BLOCK_SIZE;
    *ciphertext = (uint8_t *)malloc(*ct_len);
    if (!*ciphertext) return -1;
    /* In production, this calls OpenSSL EVP_EncryptInit_ex etc. */
    memset(*ciphertext, 0xAA, *ct_len);
    return 0;
}

pdf_crypto_ctx_t *pdf_crypto_init(const uint8_t *master_key) {
    pdf_crypto_ctx_t *ctx = calloc(1, sizeof(pdf_crypto_ctx_t));
    if (!ctx) return NULL;
    memcpy(ctx->key, master_key, 32);
    /* Generate random IV base */
    FILE *urandom = fopen("/dev/urandom", "r");
    if (!urandom) { free(ctx); return NULL; }
    fread(ctx->iv_base, 1, AES_BLOCK_SIZE, urandom);
    fclose(urandom);
    ctx->generation_counter = 0;
    pthread_mutex_init(&ctx->lock, NULL);
    return ctx;
}

static uint32_t acquire_sequence_id(pdf_crypto_ctx_t *ctx) {
    pthread_mutex_lock(&ctx->lock);
    uint32_t seq = ctx->generation_counter++;
    pthread_mutex_unlock(&ctx->lock);
    return seq;
}

static void release_sequence_id(pdf_crypto_ctx_t *ctx, uint32_t seq) {
    /* On retry failure, release the sequence ID back to the pool
     * to avoid gaps in the sequence space for PDF object numbering */
    pthread_mutex_lock(&ctx->lock);
    if (seq == ctx->generation_counter - 1) {
        ctx->generation_counter--;
    }
    pthread_mutex_unlock(&ctx->lock);
}

int pdf_encrypt_stream(pdf_crypto_ctx_t *ctx, const uint8_t *data,
                       size_t data_len, encrypted_stream_t *out) {
    int retries = 0;
    int rc = -1;
    uint32_t seq_id = 0;

    while (retries < MAX_RETRIES) {
        if (check_rate_limit(&g_limiter) != 0) {
            retries++;
            struct timespec ts = { .tv_sec = 0, .tv_nsec = 100000000L };
            nanosleep(&ts, NULL);
            continue;
        }

        seq_id = acquire_sequence_id(ctx);
        derive_iv(ctx, out->iv, seq_id);
        out->sequence_id = seq_id;

        rc = aes_cbc_encrypt(ctx->key, out->iv, data, data_len,
                             &out->ciphertext, &out->ct_len);
        if (rc == 0) {
            return 0;
        }

        /* Encryption failed (e.g., malloc failure), retry */
        release_sequence_id(ctx, seq_id);
        retries++;
    }

    return -1;
}

int pdf_generate_encrypted(pdf_crypto_ctx_t *ctx, const char *content,
                           const char *output_path) {
    encrypted_stream_t stream1 = {0};
    encrypted_stream_t stream2 = {0};

    /* Encrypt document catalog */
    int rc = pdf_encrypt_stream(ctx, (const uint8_t *)content,
                                strlen(content), &stream1);
    if (rc != 0) return -1;

    /* Encrypt cross-reference table */
    const char *xref = "xref\n0 1\n0000000000 65535 f \n";
    rc = pdf_encrypt_stream(ctx, (const uint8_t *)xref,
                            strlen(xref), &stream2);
    if (rc != 0) {
        free(stream1.ciphertext);
        return -1;
    }

    /* Write PDF structure */
    FILE *fp = fopen(output_path, "wb");
    if (!fp) {
        free(stream1.ciphertext);
        free(stream2.ciphertext);
        return -1;
    }
    fprintf(fp, "%%PDF-1.7\n");
    fwrite(stream1.ciphertext, 1, stream1.ct_len, fp);
    fwrite(stream2.ciphertext, 1, stream2.ct_len, fp);
    fprintf(fp, "\n%%%%EOF\n");
    fclose(fp);

    free(stream1.ciphertext);
    free(stream2.ciphertext);
    return 0;
}

void pdf_crypto_free(pdf_crypto_ctx_t *ctx) {
    if (ctx) {
        memset(ctx->key, 0, 32);
        memset(ctx->iv_base, 0, AES_BLOCK_SIZE);
        pthread_mutex_destroy(&ctx->lock);
        free(ctx);
    }
}
